  // A textura procedural permanece como reserva, mesmo com Base64 inválido.
  // Este projeto usa Three.js r128: nessa versão, sRGBEncoding é o equivalente
  // funcional de colorSpace = THREE.SRGBColorSpace das versões mais novas.
  function aplicarMapaMarteBase64() {
    const raw = MAPA_MARTE_BASE64.trim();
    if (!raw || raw === 'COLE_AQUI_O_BASE64_DO_MAPA') return;
    const dataUrl = /^data:image\//i.test(raw)
      ? raw.replace(/\s/g, '')
      : 'data:image/jpeg;base64,' + raw.replace(/\s/g, '');
    new THREE.TextureLoader().load(dataUrl, textura => {
      if (!mars) { textura.dispose(); return; }
      if ('colorSpace' in textura && THREE.SRGBColorSpace !== undefined)
        textura.colorSpace = THREE.SRGBColorSpace;
      else
        textura.encoding = THREE.sRGBEncoding;
      textura.anisotropy = renderer.capabilities.getMaxAnisotropy();
      textura.needsUpdate = true;
      const mat = mars.material;
      const mapaAnterior = mat.map;
      const normalAnterior = mat.normalMap;
      mat.map = textura;
      mat.normalMap = null; // evita conflito com o relevo procedural anterior
      mat.bumpMap = textura;
      mat.bumpScale = 0.03;
      mat.needsUpdate = true;
      if (mapaAnterior && mapaAnterior !== textura) mapaAnterior.dispose();
      if (normalAnterior && normalAnterior !== textura && normalAnterior !== mapaAnterior)
        normalAnterior.dispose();
    }, undefined, erro => {
      console.warn('Invalid Mars Base64 map; keeping the procedural texture.', error);
    });
  }
