  function routeLine(points,color,closed=false,r=2.018){
    const out=[];for(let i=0;i<points.length-(closed?0:1);i++){
      const a=geoPoint(...points[i],1).normalize(),b=geoPoint(...points[(i+1)%points.length],1).normalize();
      const arc=Math.acos(THREE.MathUtils.clamp(a.dot(b),-1,1));const steps=Math.max(2,Math.ceil(arc/0.004));
      for(let j=0;j<steps;j++){const q=j/steps;const v=a.clone().lerp(b,q).normalize().multiplyScalar(r);out.push(v);}
    }out.push(geoPoint(...points[closed?0:points.length-1],r));
    const geo=new THREE.BufferGeometry().setFromPoints(out),mat=new THREE.LineBasicMaterial({color,transparent:true,opacity:.55,depthTest:true,depthWrite:false});
    const line=new THREE.Line(geo,mat);line.frustumCulled=false;return line;
  }
