  const orbitalPaths=[];
  const orbitSceneGroup=new THREE.Group();orbitSceneGroup.name='Two subtle Mars orbits';scene.add(orbitSceneGroup);
  function addOrbitalTrack(id,name,color,major,minor,tilt,heading,phase,speed){
    const path=[],rotation=new THREE.Euler(tilt,heading,tilt*.25,'XYZ');
    for(let i=0;i<180;i++){const t=i/180*Math.PI*2;path.push(new THREE.Vector3(major*Math.cos(t),minor*Math.sin(t),0).applyEuler(rotation));}
    const material=new THREE.LineBasicMaterial({color,transparent:true,opacity:.28,depthWrite:false,depthTest:true});
    const line=new THREE.LineLoop(new THREE.BufferGeometry().setFromPoints(path),material);orbitSceneGroup.add(line);
    orbitalPaths.push({id,name,path,line,material,phase,speed});
  }
  addOrbitalTrack('escapade','Illustrative orbit A',0xdee7e9,3.05,2.72,.30,.20,.14,.025);
